/* global Office */

Office.onReady(() => {
  // If needed, Office.js is ready to be called.
  
});

/**
 * Shows a notification when the add-in command is executed.
 * @param event
 */
function action(event: Office.AddinCommands.Event) {
  const message: Office.NotificationMessageDetails = {
    type: Office.MailboxEnums.ItemNotificationMessageType.InformationalMessage,
    message: "Performed action.",
    icon: "Icon.80x80",
    persistent: true,
  };

  // Show a notification message.
  Office.context.mailbox.item.notificationMessages.replaceAsync(
    "ActionPerformanceNotification",
    message
  );

  // Be sure to indicate when the add-in command function is complete.
  event.completed();
}
function extractHyperlinks(event: Office.AddinCommands.Event) {
  console.log(`extractHyperlink start`);
  Excel.run(async (context) => {
    const sheet = context.workbook.worksheets.getActiveWorksheet();
    const colA = sheet.getRange("A2:A1000");
    colA.load(["values", "hyperlink"]);

    await context.sync();

    for (let i = 0; i < colA.values.length; i++) {
      const hyperlink = colA.getCell(i, 0).hyperlink;
      if (hyperlink) {
        sheet.getCell(i + 1, 15).values = [[hyperlink.address]]; // P열 = column 15 (0-indexed)
      } else {
        sheet.getCell(i + 1, 15).values = [[""]];
      }
    }

    await context.sync();
  });

  // 필수! Office에 작업 완료 알림
  event.completed();
}
function doSomething(event: Office.AddinCommands.Event) {
  console.log(`doSomething start`);
  Excel.run(async context => {
    const sheet = context.workbook.worksheets.getActiveWorksheet();
    sheet.getRange("A1").values = [["버튼 클릭 성공!"]];
    await context.sync();
  });
  event.completed();
}

// Register the function with Office.
Office.actions.associate("action", action);
Office.actions.associate("extractHyperlinks", extractHyperlinks);
Office.actions.associate("doSomething", doSomething);
